import React, { useState, useEffect } from "react";
import { Box, Typography, Button, Grid, Card, CardContent } from "@mui/material";

const backgroundImages = [
  "/Background19.jpg",
  "/Background20.jpg",
  "/Background21.jpg",
  "/Background22.jpg",
];

export default function HomePage() {
  const [currentBackground, setCurrentBackground] = useState(0);
  const [showCards, setShowCards] = useState(false); // State to control card section visibility

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentBackground((prev) => (prev + 1) % backgroundImages.length);
    }, 3000); // Background changes every 3 seconds

    return () => clearInterval(interval);
  }, []);

  // Function to handle scroll on button click and show card section
  const handleBookNowClick = () => {
    const cardSection = document.getElementById("card-section");
    if (cardSection) {
      cardSection.scrollIntoView({ behavior: "smooth" }); // Smooth scroll to card section
      setShowCards(true); // Show cards after scrolling
    }
  };

  return (
    <Box>
      {/* Home Content */}
      {!showCards && (
        <Box
          sx={{
            padding: { xs: 2, sm: 4 },
            textAlign: "center",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            minHeight: "100vh",
            backgroundImage: `url(${backgroundImages[currentBackground]})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
            transition: "background-image 0.8s ease-in-out", // Smooth transition between images
          }}
        >
          <Typography
            variant="h3"
            gutterBottom
            sx={{
              fontWeight: "bold",
              color: "#b56f76",
              fontSize: { xs: "2rem", sm: "3rem" }, // Responsive font size
            }}
          >
            EVERPLAN
          </Typography>
          <Typography
            variant="h5"
            gutterBottom
            sx={{
              fontStyle: "italic",
              color: "#6B4F4F",
              fontSize: { xs: "1.2rem", sm: "1.5rem" }, // Adjusts for smaller screens
            }}
          >
            Plan, Book, Celebrate—It’s That Easy!
          </Typography>

          <Button
            variant="contained"
            sx={{
              marginTop: 2,
              padding: "10px 20px",
              fontSize: "1rem",
              borderRadius: 2,
              width: "200px", // Smaller button width
              backgroundColor: "#F7C5AD", // Custom button color
              color: "#fff", // White text color for contrast
              "&:hover": {
                backgroundColor: "#F7C5AD", // Slightly darker shade on hover
              },
            }}
            onClick={handleBookNowClick} // Scroll to cards section
          >
            Book Now
          </Button>
        </Box>
      )}

      {/* Cardholders Section */}
      {showCards && (
        <Box
          id="card-section"
          sx={{
            padding: 4,
          }}
        >
          <Typography
            variant="h4"
            sx={{
              fontWeight: "bold",
              textAlign: "center",
              marginBottom: 3,
            }}
          >
            Explore Our Services
          </Typography>

          {/* Grid Layout for Cards */}
          <Grid container spacing={2} sx={{ justifyContent: "center" }}>
            {["venues", "hair", "makeup", "photographers", "music", "florist", "dresser", "planner"].map((tab) => (
              <Grid item xs={6} sm={4} md={3} key={tab}>
                <Card
                  sx={{
                    borderRadius: 6, // Rounded corners for the card
                    boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                    overflow: "hidden",
                    display: "flex",
                    flexDirection: "column",
                    height: "100%",
                    backgroundColor: "#fff", // White background for card
                  }}
                >
                  {/* Image Section: Replace with your custom image */}
                  <Box
                    sx={{
                      width: "100%",
                      aspectRatio: "4 / 3", // Maintain 4:3 aspect ratio for image part
                      backgroundImage: `url('/images/${tab}.jpg')`, // Example placeholder image
                      backgroundSize: "cover",
                      backgroundPosition: "center",
                    }}
                  />
                  {/* White part for title and subtitle */}
                  <CardContent
                    sx={{
                      backgroundColor: "#fff",
                      padding: 2,
                      textAlign: "center",
                    }}
                  >
                    <Typography
                      variant="h6"
                      sx={{
                        fontWeight: "bold",
                        fontSize: "calc(1.2vw + 0.8rem)",
                        textAlign: "center",
                        lineHeight: 1.2,
                        overflow: "hidden",
                        whiteSpace: "nowrap",
                        textOverflow: "ellipsis",
                      }}
                    >
                      {tab.charAt(0).toUpperCase() + tab.slice(1)}
                    </Typography>
                    <Typography
                      variant="body2"
                      color="text.secondary"
                      sx={{
                        fontSize: "calc(0.8vw + 0.6rem)",
                        textAlign: "center",
                        lineHeight: 1,
                        overflow: "hidden",
                        whiteSpace: "nowrap",
                        textOverflow: "ellipsis",
                        marginTop: 1,
                      }}
                    >
                      Description for {tab}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Box>
      )}
    </Box>
  );
}


